import axios, { CancelToken } from 'axios';

interface FetchResponse<T = any> {
  promise: Promise<T>;
  cancel: () => void;
}

export function fetchWithCancel(url: string): FetchResponse {
  const source = axios.CancelToken.source();

  const promise = axios.get(url, {
