// FILE: CounterPanel.tsx
import React from 'react';

interface CounterPanelProps {
  initialCount?: number;
  step?: number;
  label: string;
}

interface CounterPanelState {
  count: number;
  clicks: number;
}

class CounterPanel extends React.Component<CounterPanelProps, CounterPanelState> {
  constructor(props: CounterPanelProps) {
    super(props);
    this.state = {
      count: props.initialCount ?? 0,
      clicks: 0,
    };
  }

  componentDidMount(): void {
    console.info('CounterPanel mounted', this.props.label);
  }

  componentWillUnmount(): void {
    console.info('CounterPanel unmounted', this.props.label);
  }

  handleIncrement = (): void => {
    const step = this.props.step ?? 1;
    this.setState((prevState) => ({
      count: prevState.count + step,
      clicks: prevState.clicks + 1,
    }));
  };

  handleDecrement = (): void => {
    const step = this.props.step ?? 1;
    this.setState((prevState) => ({
      count: prevState.count - step,
      clicks: prevState.clicks + 1,
    }));
  };

  handleReset = (): void => {
    this.setState((prevState) => ({
      count: this.props.initialCount ?? 0,
      clicks: prevState.clicks + 1,
    }));
  };

  render() {
    return (
      <div>
        <h3>{this.props.label}</h3>
        <p>Count: {this.state.count}</p>
        <p>Clicks: {this.state.clicks}</p>
        <button onClick={this.handleIncrement}>+</button>
        <button onClick={this.handleDecrement}>-</button>
        <button onClick={this.handleReset}>Reset</button>
      </div>
    );
  }
}

export default CounterPanel;

