import axios from 'axios';
import { format } from 'date-fns';

interface TodoItem {
  id: string;
  text: string;
  createdAt: Date;
}

interface TodoListProps {
  items: TodoItem[];
}

const TodoList: React.FC<TodoListProps> = ({ items }) => {
