  }, []);

  return (
    <ul>
      {todos.map((item, index) => (
        <li key={item.id}>
          {item.text} - {format(new Date(item.createdAt), 'yyyy-MM-dd')}
        </li>
      ))}
    </ul>
  );
};

export default TodoList;

