// FILE: http-get.ts
/**
 * Makes an HTTP GET request using XMLHttpRequest and returns the parsed JSON body.
 * @template T - The type of the expected JSON response
 * @param url - The URL to fetch
 * @returns A promise that resolves with the parsed JSON response
 * @throws Error if the request fails, times out, or receives a non-2xx status code
 */
export function getJson<T>(url: string): Promise<T> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();

    // Open a GET request
    xhr.open('GET', url);

    // Set response type to json for automatic parsing
    xhr.responseType = 'json';

    // Handle successful completion
    xhr.onload = (): void => {
      // Check for successful status codes (200-299)
      if (xhr.status >= 200 && xhr.status < 300) {
        const response: T = xhr.response;
        resolve(response);
      } else {
        reject(
          new Error(
            `HTTP Error: ${xhr.status} ${xhr.statusText}`
          )
        );
      }
    };

    // Handle network errors
    xhr.onerror = (): void => {
      reject(new Error('Network error'));
    };

    // Handle request timeout
    xhr.ontimeout = (): void => {
      reject(new Error('Request timeout'));
    };

    // Send the request
    xhr.send();
  });
}

